// Explicit paid vision probe using only labels generated by our fixture script.
import {
  type Input,
  validateSuggestion,
  validImage,
} from "../supabase/functions/coffee-assistance/handler.ts";
import { generate } from "../supabase/functions/coffee-assistance/provider.ts";
const key = Deno.env.get("OPENAI_API_KEY") ?? "";
const model = Deno.env.get("MUGSHOT_AI_MODEL") ?? "";
if (!key || model !== "gpt-6-luna" || Deno.args.length !== 2) {
  throw Error("Approved model and two synthetic JPEG paths required");
}
for (const [index, task] of ["bag_scan", "recipe_import"].entries()) {
  const bytes = await Deno.readFile(Deno.args[index]);
  const image = "data:image/jpeg;base64," + btoa(String.fromCharCode(...bytes));
  if (!validImage(image)) {
    throw Error("Synthetic image does not meet server bounds");
  }
  const input: Input = {
    owner_id: "11111111-1111-4111-8111-111111111111",
    request_id: crypto.randomUUID(),
    consent_version: "selected-details-v1",
    task: task as Input["task"],
    query:
      "Read this original fictional fixture. I created it and permit copying. Extract only printed fields.",
    evidence: [],
    image,
  };
  const result = validateSuggestion(
    await generate(input, { key, model }, new AbortController().signal),
    input,
  );
  if (!result) throw Error(`Invalid synthetic ${task} result`);
  if (
    task === "bag_scan" &&
    !result.fields.some((x) => x.key === "origin" && /colombia/i.test(x.value))
  ) throw Error("Printed origin not extracted");
  if (
    task === "recipe_import" &&
    !result.fields.some((x) =>
      x.key === "ingredient" && /10\s*g/i.test(x.value)
    )
  ) throw Error("Printed recipe quantity not preserved");
  console.log(
    `PASS synthetic image ${task}: printed fields extracted from image-only input; no user content`,
  );
}
